function bayLedger(bays, operations) {
  const counts = new Array(bays + 1).fill(0);
  const reports = [];
  for (const op of operations) {
    if (op[0] === "set") {
      counts[op[1]] = op[2];
    } else if (op[0] === "total") {
      let sum = 0;
      for (let bay = 1; bay <= op[1]; bay++) sum += counts[bay];
      reports.push(sum);
    } else {
      let sum = 0;
      let found = -1;
      for (let bay = 1; bay <= bays && found === -1; bay++) {
        sum += counts[bay];
        if (sum >= op[1]) found = bay;
      }
      reports.push(found);
    }
  }
  return reports;
}

function bayLedger(bays, operations) {
  const size = Math.max(1, Math.ceil(Math.sqrt(bays)));
  const counts = new Int32Array(bays + 1);
  const blockSum = new Float64Array(Math.floor(bays / size) + 1);
  const reports = [];
  for (const op of operations) {
    if (op[0] === "set") {
      blockSum[Math.floor((op[1] - 1) / size)] += op[2] - counts[op[1]];
      counts[op[1]] = op[2];
    } else if (op[0] === "total") {
      const upto = op[1];
      const fullBlocks = Math.floor(upto / size);
      let sum = 0;
      for (let block = 0; block < fullBlocks; block++) sum += blockSum[block];
      for (let bay = fullBlocks * size + 1; bay <= upto; bay++) sum += counts[bay];
      reports.push(sum);
    } else {
      let remaining = op[1];
      let block = 0;
      while (block * size < bays && blockSum[block] < remaining) {
        remaining -= blockSum[block];
        block++;
      }
      let found = -1;
      for (let bay = block * size + 1; bay <= Math.min(bays, (block + 1) * size) && found === -1; bay++) {
        remaining -= counts[bay];
        if (remaining <= 0) found = bay;
      }
      reports.push(found);
    }
  }
  return reports;
}

function bayLedger(bays, operations) {
  const tree = new Float64Array(bays + 1);
  const held = new Int32Array(bays + 1);
  let top = 1;
  while (top * 2 <= bays) top *= 2;
  const reports = [];
  for (const op of operations) {
    if (op[0] === "set") {
      const change = op[2] - held[op[1]];
      held[op[1]] = op[2];
      for (let at = op[1]; at <= bays; at += at & -at) tree[at] += change;
    } else if (op[0] === "total") {
      let sum = 0;
      for (let at = op[1]; at > 0; at -= at & -at) sum += tree[at];
      reports.push(sum);
    } else {
      let at = 0;
      let remaining = op[1];
      for (let step = top; step > 0; step >>= 1) {
        if (at + step <= bays && tree[at + step] < remaining) {
          at += step;
          remaining -= tree[at];
        }
      }
      reports.push(at + 1 <= bays ? at + 1 : -1);
    }
  }
  return reports;
}
